arguments.command:
curl -s -X POST https://slack.com/api/users.list -H "Authorization: Bearer <TOKEN>" -d "limit=1000" | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'): print('ERR',d); sys.exit()
for u in d['members']:
    name=((u.get('real_name') or '')+' '+(u.get('profile',{}).get('display_name') or '')+' '+(u.get('profile',{}).get('team',{}).get('name','') if isinstance(u.get('profile',{}).get('team'),dict) else '')).lower()
    if 'diego' in name or 'alvarez' in name or 'alvarado' in name:
        print('MATCH:',u['id'],'|',u.get('real_name'),'|',u.get('deleted'))
print('member count:', len(d['members']))
"

